(7353997, 1150778, 149964, '<td valign="top">I like that this is in B&amp;W.</td>', 'I like that this is in B&W.', '2015-05-27 08:17:37.000000', NULL, 1),
(7353998, 1150397, 149964, '<td valign="top">I like the different lines and curves on this.</td>', 'I like the different lines and curves on this.', '2015-05-27 08:18:30.000000', NULL, 1),
(7353999, 1150855, 149964, '<td valign="top">I like the reflection on this. Would have preferred more colour.</td>', 'I like the reflection on this. Would have preferred more colour.', '2015-05-27 08:19:14.000000', NULL, 1),
(7354000, 1150689, 149964, '<td valign="top">Like the symmetry on this - spot on!</td>', 'Like the symmetry on this - spot on!', '2015-05-27 08:19:42.000000', NULL, 1),
