(7354002, 1150685, 149964, '<td valign="top">Lovely view, nice and sharp and I like the composition; what a shame the weather was grey.</td>', 'Lovely view, nice and sharp and I like the composition; what a shame the weather was grey.', '2015-05-27 08:22:06.000000', NULL, 1),
(7354008, 1150493, 128323, '<td valign="top">Nice detail and tonal range.</td>', 'Nice detail and tonal range.', '2015-05-27 09:02:38.000000', NULL, 1),
(7354009, 1150739, 128323, '<td valign="top">Ha!  Great take on the challenge.</td>', 'Ha!  Great take on the challenge.', '2015-05-27 09:04:11.000000', NULL, 1),
(7354010, 1150733, 128323, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2015-05-27 09:04:32.000000', NULL, 1),
(7354011, 1150529, 128323, '<td valign="top">Wow, this draws you right in.  Love the leading lines and symmetry.</td>', 'Wow, this draws you right in.  Love the leading lines and symmetry.', '2015-05-27 09:05:23.000000', NULL, 1),
(7354012, 1150562, 128323, '<td valign="top">Looks very peaceful!  I like the sepia tone, but am a bit distracted by the halos around the trees.</td>', 'Looks very peaceful!  I like the sepia tone, but am a bit distracted by the halos around the trees.', '2015-05-27 09:05:54.000000', NULL, 1),
(7354018, 1150555, 128323, '<td valign="top">The detail in the bridge and starbursts on the lights are great here.</td>', 'The detail in the bridge and starbursts on the lights are great here.', '2015-05-27 09:10:38.000000', NULL, 1),
(7354019, 1150779, 128323, '<td valign="top">Wow.  Winner!  This has a magical mood to it.</td>', 'Wow.  Winner!  This has a magical mood to it.', '2015-05-27 09:11:19.000000', NULL, 1),
(7354021, 1150360, 128323, '<td valign="top">This is a great subject, and I like the composition.  The heavy border and over-dark clouds are a bit distracting though.  6</td>', 'This is a great subject, and I like the composition.  The heavy border and over-dark clouds are a bit distracting though.  6', '2015-05-27 09:12:57.000000', NULL, 1),
(7354023, 1150517, 128323, '<td valign="top">Great colors!  I like the soft look of this too.</td>', 'Great colors!  I like the soft look of this too.', '2015-05-27 09:14:57.000000', NULL, 1),
(7354051, 1150606, 39679, '<td valign="top">This is a great shot but I really wish there were a little more of the buildings./</td>', 'This is a great shot but I really wish there were a little more of the buildings./', '2015-05-27 11:28:10.000000', NULL, 1),
(7354053, 1150805, 177322, '<td valign="top">The gossamer quality is quite enchanting.</td>', 'The gossamer quality is quite enchanting.', '2015-05-27 11:38:29.000000', NULL, 1),
