(7354082, 1150778, 16046, '<td valign="top">Should do well, top 5</td>', 'Should do well, top 5', '2015-05-27 12:13:47.000000', NULL, 1),
(7354207, 1150831, 2553, '<td valign="top">While I am a true believer in this, and respect your view of this fitting into the challenge; for me, it is not "in the spirit of the challenge" in a challenge for Bridges.</td>', 'While I am a true believer in this, and respect your view of this fitting into the challenge; for me, it is not "in the spirit of the challenge" in a challenge for Bridges.', '2015-05-27 16:33:21.000000', NULL, 1),
(7354217, 1150855, 2553, '<td valign="top">The texture in the bridge is pretty cool, even though the processing is a little over the top for my taste.  The image seems to have a slightly desaturated look, which kind of suits it.</td>', 'The texture in the bridge is pretty cool, even though the processing is a little over the top for my taste.  The image seems to have a slightly desaturated look, which kind of suits it.', '2015-05-27 16:58:15.000000', NULL, 1),
(7354218, 1150856, 2553, '<td valign="top">Wow, this is what it looks like near me, in Texas, right now.</td>', 'Wow, this is what it looks like near me, in Texas, right now.', '2015-05-27 17:05:11.000000', NULL, 1),
(7354308, 1150381, 125410, '<td valign="top">Lovely composure</td>', 'Lovely composure', '2015-05-27 19:59:41.000000', NULL, 1),
(7354310, 1150840, 125410, '<td valign="top">HDR on the clouds feels a bit heavy... but somehow it works well in this shot.</td>', 'HDR on the clouds feels a bit heavy... but somehow it works well in this shot.', '2015-05-27 20:02:55.000000', NULL, 1),
(7354312, 1150779, 125410, '<td valign="top">The edges with the sky are a bit sharp... but the shot is beautiful.</td>', 'The edges with the sky are a bit sharp... but the shot is beautiful.', '2015-05-27 20:07:01.000000', NULL, 1),
(7354314, 1150739, 125410, '<td valign="top">Bit of a theme stretch (get it?), but an excellent shot!</td>', 'Bit of a theme stretch (get it?), but an excellent shot!', '2015-05-27 20:08:09.000000', NULL, 1),
(7354324, 1150517, 16106, '<td valign="top">A lovely set of textures here, especially in the water, and while the rays of the sun work well, I expect some will object to the lens flare stealing the drama from the stand of trees.</td>', 'A lovely set of textures here, especially in the water, and while the rays of the sun work well, I expect some will object to the lens flare stealing the drama from the stand of trees.', '2015-05-27 20:30:31.000000', NULL, 1),
(7354325, 1150778, 16106, '<td valign="top">Great heft and drama with perhaps a bit too much contrast. The underside of the bridge and the buildings could have used some more middle grays. Top 5</td>', 'Great heft and drama with perhaps a bit too much contrast. The underside of the bridge and the buildings could have used some more middle grays. Top 5', '2015-05-27 20:32:56.000000', NULL, 1),
(7354326, 1150606, 16106, '<td valign="top">Lovely the softness of the reflections balance out well against the crispness of the buildings, yet I find myself scrolling up for a bit more of the buildings than are in the frame. Ought to ribbon.</td>', 'Lovely the softness of the reflections balance out well against the crispness of the buildings, yet I find myself scrolling up for a bit more of the buildings than are in the frame. Ought to ribbon.', '2015-05-27 20:34:47.000000', NULL, 1),
(7354327, 1150493, 23484, '<td valign="top">Beautiful b&amp;w image.</td>', 'Beautiful b&w image.', '2015-05-27 20:34:56.000000', NULL, 1),
(7354328, 1150565, 23484, '<td valign="top">I like the perspective on this. Nice b&amp;w.</td>', 'I like the perspective on this. Nice b&w.', '2015-05-27 20:35:38.000000', NULL, 1),
(7354329, 1150843, 23484, '<td valign="top">The perspective and the fish eye make this incredible.</td>', 'The perspective and the fish eye make this incredible.', '2015-05-27 20:36:10.000000', NULL, 1),
(7354331, 1150386, 23484, '<td valign="top">Nice drink and nice view.</td>', 'Nice drink and nice view.', '2015-05-27 20:37:16.000000', NULL, 1),
(7354332, 1150840, 23484, '<td valign="top">Nice stark processing.</td>', 'Nice stark processing.', '2015-05-27 20:37:58.000000', NULL, 1),
(7354333, 1150685, 16106, '<td valign="top">Beautiful stillness you captured, and I like the softness of the water and the quiet colors. I would have liked a bigger image to bring me closer that you could have gotten by editing out the top 1/4 that does not add much to the story for me.</td>', 'Beautiful stillness you captured, and I like the softness of the water and the quiet colors. I would have liked a bigger image to bring me closer that you could have gotten by editing out the top 1/4 that does not add much to the story for me.', '2015-05-27 20:38:01.000000', NULL, 1),
(7354334, 1150705, 23484, '<td valign="top">Can''t play without the bridge.</td>', 'Can''t play without the bridge.', '2015-05-27 20:38:41.000000', NULL, 1),
(7354336, 1150779, 23484, '<td valign="top">Nice perspective and nice long exposure.</td>', 'Nice perspective and nice long exposure.', '2015-05-27 20:39:14.000000', NULL, 1),
(7354338, 1150704, 23484, '<td valign="top">The processing is so cool.</td>', 'The processing is so cool.', '2015-05-27 20:39:31.000000', NULL, 1),
(7354339, 1150756, 23484, '<td valign="top">Never saw one of those before. Very cool.</td>', 'Never saw one of those before. Very cool.', '2015-05-27 20:40:06.000000', NULL, 1),
(7354340, 1150805, 23484, '<td valign="top">The bridge to your dreams.</td>', 'The bridge to your dreams.', '2015-05-27 20:40:23.000000', NULL, 1),
(7354341, 1150733, 23484, '<td valign="top">The foreground really adds a lot.</td>', 'The foreground really adds a lot.', '2015-05-27 20:40:57.000000', NULL, 1),
(7354342, 1150860, 23484, '<td valign="top">Great symmetry.</td>', 'Great symmetry.', '2015-05-27 20:41:26.000000', NULL, 1),
(7354343, 1150850, 23484, '<td valign="top">Nice view of the ride.</td>', 'Nice view of the ride.', '2015-05-27 20:41:55.000000', NULL, 1),
(7354344, 1150562, 16106, '<td valign="top">I find the bottom of the frame with the just barely there plant life along the bottom of the frame at odds with all the big empty sky, and it bothers me more than it ought to. the bridge, the reflection, and the bicyclist are all well captured but the framing creates a tension that seems at odds with the lovely scene. <br/>A top ten that could have been more IMHO.</td>', 'I find the bottom of the frame with the just barely there plant life along the bottom of the frame at odds with all the big empty sky, and it bothers me more than it ought to. the bridge, the reflection, and the bicyclist are all well captured but the framing creates a tension that seems at odds with the lovely scene. A top ten that could have been more IMHO.', '2015-05-27 20:43:33.000000', NULL, 1),
(7354345, 1150851, 16106, '<td valign="top">Wow. Just lovely. I had to google the bridge, and this is far and away a better shot than anything above the roadway. the inclusion of those shiny rocks in the foreground really make the shot sing. Ought to ribbon.</td>', 'Wow. Just lovely. I had to google the bridge, and this is far and away a better shot than anything above the roadway. the inclusion of those shiny rocks in the foreground really make the shot sing. Ought to ribbon.', '2015-05-27 20:45:41.000000', NULL, 1),
(7354346, 1150840, 16106, '<td valign="top">Not the sexiest bridge in the challenge, but I think you squeezed all the drama you could out of what you were working with. Well framed to bring in that lovely cloud filled sky and the on coming ship.</td>', 'Not the sexiest bridge in the challenge, but I think you squeezed all the drama you could out of what you were working with. Well framed to bring in that lovely cloud filled sky and the on coming ship.', '2015-05-27 20:47:59.000000', NULL, 1),
(7354348, 1150545, 16106, '<td valign="top">You set a beautiful mood here with just the right amount of softness. Putting the action of the stream into the corner is a nice balance for all the quite in the rest of the frame.</td>', 'You set a beautiful mood here with just the right amount of softness. Putting the action of the stream into the corner is a nice balance for all the quite in the rest of the frame.', '2015-05-27 20:49:54.000000', NULL, 1),
(7354349, 1150386, 16106, '<td valign="top">I hope you explain how you got the near and far in focus with a blurry middle ground in your notes. Free lensing? I need to know. A pleasing peaceful composition.</td>', 'I hope you explain how you got the near and far in focus with a blurry middle ground in your notes. Free lensing? I need to know. A pleasing peaceful composition.', '2015-05-27 20:50:30.000000', NULL, 1),
(7354350, 1150791, 16106, '<td valign="top">Nice softness of a long exposure to set a brooding tone. A bit too much extraneous buildings on the left, I think one block would have done for setting, but the stuff on the right is perfectly captured.</td>', 'Nice softness of a long exposure to set a brooding tone. A bit too much extraneous buildings on the left, I think one block would have done for setting, but the stuff on the right is perfectly captured.', '2015-05-27 20:54:29.000000', NULL, 1),
