INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7354460, 1150604, 98141, '<td valign="top">Way out of focus on my screen. Original interpretation of the challenge title!</td>', 'Way out of focus on my screen. Original interpretation of the challenge title!', '2015-05-28 00:06:43.000000', NULL, 1),
(7354464, 1150779, 98141, '<td valign="top">My favorite from the challenge!</td>', 'My favorite from the challenge!', '2015-05-28 00:12:08.000000', NULL, 1),
(7354511, 1150727, 83149, '<td valign="top">Not liking the blurry boat and I find the railing in front too distracting in this image.</td>', 'Not liking the blurry boat and I find the railing in front too distracting in this image.', '2015-05-28 07:55:25.000000', NULL, 1),
(7354513, 1150565, 83149, '<td valign="top">It''s a nice shot, but there is a lack of sharpness, and the girders on the left have some jaggies.</td>', 'It''s a nice shot, but there is a lack of sharpness, and the girders on the left have some jaggies.', '2015-05-28 08:01:44.000000', NULL, 1),
(7354514, 1150335, 83149, '<td valign="top">I find the green light in the water distracting and takes away from the image.</td>', 'I find the green light in the water distracting and takes away from the image.', '2015-05-28 08:05:40.000000', NULL, 1),
(7354515, 1150529, 83149, '<td valign="top">Love the symmetry and the perspective.</td>', 'Love the symmetry and the perspective.', '2015-05-28 08:12:22.000000', NULL, 1),
(7354619, 1150529, 159723, '<td valign="top">Love it!</td>', 'Love it!', '2015-05-28 13:22:39.000000', NULL, 1),
(7354620, 1150843, 159723, '<td valign="top">Cool shot!</td>', 'Cool shot!', '2015-05-28 13:23:11.000000', NULL, 1),
(7354621, 1150864, 159723, '<td valign="top">Think looks like an old painting! Lovely!</td>', 'Think looks like an old painting! Lovely!', '2015-05-28 13:23:49.000000', NULL, 1),
(7354623, 1150685, 159723, '<td valign="top">Lovely mute colours!</td>', 'Lovely mute colours!', '2015-05-28 13:24:54.000000', NULL, 1),
(7354625, 1150685, 163081, '<td valign="top">This must be the winner. Seen a thousand times but love your processing. A 10 from me</td>', 'This must be the winner. Seen a thousand times but love your processing. A 10 from me', '2015-05-28 13:44:55.000000', NULL, 1),
